body:
It's probably also worth noting the MLT query produces an exception when the documents only have the empty field

```
PUT test
{
  "settings": {
    "number_of_shards": 1,
    "number_of_replicas": 0
  }, 
  "mappings": {
    "_doc": {
      "properties": {
        "nothing": {
          "type": "text"
        }
      }
    }
  }
}

POST /_bulk
{ "index":  { "_index": "test", "_type": "_doc","_id":1}}
{"nothing": ""}
{ "index":  { "_index": "test", "_type": "_doc","_id":2}}
{"nothing": ""}

GET /_search
{
  "query": {
    "more_like_this": {
      "fields": [
        "nothing"
      ],
      "like": [
        {
          "_index": "test",
          "_type": "_doc",
          "_id": "1"
        }
      ],
      "min_term_freq": 1,
      "min_doc_freq": 1
    }
  }
}
```

